/// <summary>
/// Extension of InventParameters table for adding reference to new number sequence
/// </summary>
[ExtensionOf(tableStr(InventParameters))]
public final class METInventParameters_Extension
{
}

Method.Source:
/// <summary>
/// added reference to metloadId
/// </summary>
/// <returns>NumberSequenceReference</returns>
static NumberSequenceReference numRefMetLoadID()
{
    return NumberSeqReference::findReference(extendedTypeNum(MetLoadId));
}

/// <summary>
/// add new NumberSequenceReference MetShipmentId
/// </summary>
/// <returns>NumberSequenceReference</returns>
static NumberSequenceReference numRefMetShippingID()
{
    return NumberSeqReference::findReference(extendedTypeNum(MetShipmentId));
}
